import{_ as l,a0 as p,w as o,s as c,ao as h,I as t,x as a,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在 CentOS 8 上安装和配置 Postfix 邮件服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 8 上安装和配置 Postfix 邮件服务器 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 8 上安装和配置 Postfix 邮件服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 8 上安装和配置 Postfix 邮件服务器 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191113 How to install and Configure Postfix Mail Server on CentOS 8","title":"如何在 CentOS 8 上安装和配置 Postfix 邮件服务器","tag":"201911","desc":""},"relativePath":"201911/20191113 How to install and Configure Postfix Mail Server on CentOS 8.md","filePath":"[post].md"}'),d={name:"201911/20191113 How to install and Configure Postfix Mail Server on CentOS 8.md"};function r(g,s,k,f,u,b){const i=p("Link");return o(),c("div",null,[s[15]||(s[15]=h(`<h1 id="如何在-centos-8-上安装和配置-postfix-邮件服务器" tabindex="-1">如何在 CentOS 8 上安装和配置 Postfix 邮件服务器 <a class="header-anchor" href="#如何在-centos-8-上安装和配置-postfix-邮件服务器" aria-label="Permalink to “如何在 CentOS 8 上安装和配置 Postfix 邮件服务器”">​</a></h1><p>Postfix 是一个自由开源的 MTA（邮件传输代理），用于在 Linux 系统上路由或传递电子邮件。在本指南中，你将学习如何在 CentOS 8 上安装和配置 Postfix。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Install-configure-Postfx-Server-CentOS8.jpg" alt="Install-configure-Postfx-Server-CentOS8"></p><p>实验室设置：</p><ul><li>系统：CentOS 8 服务器</li><li>IP 地址：192.168.1.13</li><li>主机名：server1.crazytechgeek.info（确保域名指向服务器的 IP）</li></ul><h3 id="步骤-1-更新系统" tabindex="-1">步骤 1）更新系统 <a class="header-anchor" href="#步骤-1-更新系统" aria-label="Permalink to “步骤 1）更新系统”">​</a></h3><p>第一步是确保系统软件包是最新的。为此，请按如下所示更新系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf update</span></span></code></pre></div><p>继续之前，还请确保不存在其他 MTA（如 Sendmail），因为这将导致与 Postfix 配置冲突。例如，要删除 Sendmail，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf remove sendmail</span></span></code></pre></div><h3 id="步骤-2-设置主机名并更新-etc-hosts" tabindex="-1">步骤 2）设置主机名并更新 /etc/hosts <a class="header-anchor" href="#步骤-2-设置主机名并更新-etc-hosts" aria-label="Permalink to “步骤 2）设置主机名并更新 /etc/hosts”">​</a></h3><p>使用下面的 <code>hostnamectl</code> 命令在系统上设置主机名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hostnamectl set-hostname server1.crazytechgeek.info</span></span>
<span class="line"><span># exec bash</span></span></code></pre></div><p>此外，你需要在 <code>/etc/hosts</code> 中添加系统的主机名和 IP：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vim /etc/hosts</span></span>
<span class="line"><span>192.168.1.13   server1.crazytechgeek.info</span></span></code></pre></div><p>保存并退出文件。</p><h3 id="步骤-3-安装-postfix-邮件服务器" tabindex="-1">步骤 3）安装 Postfix 邮件服务器 <a class="header-anchor" href="#步骤-3-安装-postfix-邮件服务器" aria-label="Permalink to “步骤 3）安装 Postfix 邮件服务器”">​</a></h3><p>验证系统上没有其他 MTA 在运行后，运行以下命令安装 Postfix：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install postfix</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Install-Postfix-Centos8.png" alt="Install-Postfix-Centos8"></p><h3 id="步骤-4-启动并启用-postfix-服务" tabindex="-1">步骤 4）启动并启用 Postfix 服务 <a class="header-anchor" href="#步骤-4-启动并启用-postfix-服务" aria-label="Permalink to “步骤 4）启动并启用 Postfix 服务”">​</a></h3><p>成功安装 Postfix 后，运行以下命令启动并启用 Postfix 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl start postfix</span></span>
<span class="line"><span># systemctl enable postfix</span></span></code></pre></div><p>要检查 Postfix 状态，请运行以下 <code>systemctl</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl status postfix</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Start-Postfix-check-status-centos8.png" alt="Start-Postfix-check-status-centos8"></p><p>太好了，我们已经验证了 Postfix 已启动并正在运行。接下来，我们将配置 Postfix 从本地发送邮件到我们的服务器。</p><h3 id="步骤-5-安装-mailx-邮件客户端" tabindex="-1">步骤 5）安装 mailx 邮件客户端 <a class="header-anchor" href="#步骤-5-安装-mailx-邮件客户端" aria-label="Permalink to “步骤 5）安装 mailx 邮件客户端”">​</a></h3><p>在配置 Postfix 服务器之前，我们需要安装 <code>mailx</code>，要安装它，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install mailx</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Install-Mailx-CentOS8.png" alt="Install-Mailx-CentOS8"></p><h3 id="步骤-6-配置-postfix-邮件服务器" tabindex="-1">步骤 6）配置 Postfix 邮件服务器 <a class="header-anchor" href="#步骤-6-配置-postfix-邮件服务器" aria-label="Permalink to “步骤 6）配置 Postfix 邮件服务器”">​</a></h3><p>Postfix 的配置文件位于 <code>/etc/postfix/main.cf</code> 中。我们需要对配置文件进行一些修改，因此请使用你喜欢的文本编辑器将其打开：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/postfix/main.cf</span></span></code></pre></div><p>更改以下几行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>myhostname = server1.crazytechgeek.info</span></span>
<span class="line"><span>mydomain = crazytechgeek.info</span></span>
<span class="line"><span>myorigin = $mydomain</span></span>
<span class="line"><span>## 取消注释并将 inet_interfaces 设置为 all##</span></span>
<span class="line"><span>inet_interfaces = all</span></span>
<span class="line"><span>## 更改为 all ##</span></span>
<span class="line"><span>inet_protocols = all</span></span>
<span class="line"><span>## 注释 ##</span></span>
<span class="line"><span>#mydestination = $myhostname, localhost.$mydomain, localhost</span></span>
<span class="line"><span>## 取消注释 ##</span></span>
<span class="line"><span>mydestination = $myhostname, localhost.$mydomain, localhost, $mydomain</span></span>
<span class="line"><span>## 取消注释并添加 IP 范围 ##</span></span>
<span class="line"><span>mynetworks = 192.168.1.0/24, 127.0.0.0/8</span></span>
<span class="line"><span>## 取消注释 ##</span></span>
<span class="line"><span>home_mailbox = Maildir/</span></span></code></pre></div><p>完成后，保存并退出配置文件。重新启动 postfix 服务以使更改生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart postfix</span></span></code></pre></div><h3 id="步骤-7-测试-postfix-邮件服务器" tabindex="-1">步骤 7）测试 Postfix 邮件服务器 <a class="header-anchor" href="#步骤-7-测试-postfix-邮件服务器" aria-label="Permalink to “步骤 7）测试 Postfix 邮件服务器”">​</a></h3><p>测试我们的配置是否有效，首先，创建一个测试用户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># useradd postfixuser</span></span>
<span class="line"><span># passwd postfixuser</span></span></code></pre></div><p>接下来，运行以下命令，从本地用户 <code>pkumar</code> 发送邮件到另一个用户 <code>postfixuser</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># telnet localhost smtp</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span># telnet localhost 25</span></span></code></pre></div><p>如果未安装 telnet 服务，那么可以使用以下命令进行安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install telnet -y</span></span></code></pre></div><p>如前所述运行命令时，应获得如下输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# telnet localhost 25</span></span>
<span class="line"><span>Trying 127.0.0.1...</span></span>
<span class="line"><span>Connected to localhost.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span>
<span class="line"><span>220 server1.crazytechgeek.info ESMTP Postfix</span></span></code></pre></div><p>上面的结果确认与 postfix 邮件服务器的连接正常。接下来，输入命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ehlo localhost</span></span></code></pre></div><p>输出看上去像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>250-server1.crazytechgeek.info</span></span>
<span class="line"><span>250-PIPELINING</span></span>
<span class="line"><span>250-SIZE 10240000</span></span>
<span class="line"><span>250-VRFY</span></span>
<span class="line"><span>250-ETRN</span></span>
<span class="line"><span>250-STARTTLS</span></span>
<span class="line"><span>250-ENHANCEDSTATUSCODES</span></span>
<span class="line"><span>250-8BITMIME</span></span>
<span class="line"><span>250-DSN</span></span>
<span class="line"><span>250 SMTPUTF8</span></span></code></pre></div><p>接下来，运行橙色高亮的命令，例如 <code>mail from</code>、<code>rcpt to</code>、<code>data</code>，最后输入 <code>quit</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mail from:&lt;pkumar&gt;</span></span>
<span class="line"><span>250 2.1.0 Ok</span></span>
<span class="line"><span>rcpt to:&lt;postfixuser&gt;</span></span>
<span class="line"><span>250 2.1.5 Ok</span></span>
<span class="line"><span>data</span></span>
<span class="line"><span>354 End data with &lt;CR&gt;&lt;LF&gt;.&lt;CR&gt;&lt;LF&gt;</span></span>
<span class="line"><span>Hello, Welcome to my mailserver (Postfix)</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>250 2.0.0 Ok: queued as B56BF1189BEC</span></span>
<span class="line"><span>quit</span></span>
<span class="line"><span>221 2.0.0 Bye</span></span>
<span class="line"><span>Connection closed by foreign host</span></span></code></pre></div><p>完成 <code>telnet</code> 命令可从本地用户 <code>pkumar</code> 发送邮件到另一个本地用户 <code>postfixuser</code>，如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Send-email-with-telnet-centos8.png" alt="Send-email-with-telnet-centos8"></p><p>如果一切都按计划进行，那么你应该可以在新用户的家目录中查看发送的邮件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls /home/postfixuser/Maildir/new</span></span>
<span class="line"><span>1573580091.Vfd02I20050b8M635437.server1.crazytechgeek.info</span></span>
<span class="line"><span>#</span></span></code></pre></div><p>要阅读邮件，只需使用 cat 命令，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /home/postfixuser/Maildir/new/1573580091.Vfd02I20050b8M635437.server1.crazytechgeek.info</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Read-postfix-email-linux.png" alt="Read-postfix-email-linux"></p><h3 id="postfix-邮件服务器日志" tabindex="-1">Postfix 邮件服务器日志 <a class="header-anchor" href="#postfix-邮件服务器日志" aria-label="Permalink to “Postfix 邮件服务器日志”">​</a></h3><p>Postfix 邮件服务器邮件日志保存在文件 <code>/var/log/maillog</code> 中，使用以下命令查看实时日志，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tail -f /var/log/maillog</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/postfix-maillogs-centos8.png" alt="postfix-maillogs-centos8"></p><h3 id="保护-postfix-邮件服务器" tabindex="-1">保护 Postfix 邮件服务器 <a class="header-anchor" href="#保护-postfix-邮件服务器" aria-label="Permalink to “保护 Postfix 邮件服务器”">​</a></h3><p>建议始终确保客户端和 Postfix 服务器之间的通信安全，这可以使用 SSL 证书来实现，它们可以来自受信任的权威机构或自签名证书。在本教程中，我们将使用 <code>openssl</code> 命令生成用于 Postfix 的自签名证书，</p><p>我假设 <code>openssl</code> 已经安装在你的系统上，如果未安装，请使用以下 <code>dnf</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install openssl -y</span></span></code></pre></div><p>使用下面的 <code>openssl</code> 命令生成私钥和 CSR（证书签名请求）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># openssl req -nodes -newkey rsa:2048 -keyout mail.key -out mail.csr</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Postfix-Key-CSR-CentOS8.png" alt="Postfix-Key-CSR-CentOS8"></p><p>现在，使用以下 openssl 命令生成自签名证书：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># openssl x509 -req -days 365 -in mail.csr -signkey mail.key -out mail.crt</span></span>
<span class="line"><span>Signature ok</span></span>
<span class="line"><span>subject=C = IN, ST = New Delhi, L = New Delhi, O = IT, OU = IT, CN = server1.crazytechgeek.info, emailAddress = root@linuxtechi</span></span>
<span class="line"><span>Getting Private key</span></span>
<span class="line"><span>#</span></span></code></pre></div><p>现在将私钥和证书文件复制到 <code>/etc/postfix</code> 目录下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cp mail.key mail.crt /etc/postfix</span></span></code></pre></div><p>在 Postfix 配置文件中更新私钥和证书文件的路径：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/postfix/main.cf</span></span>
<span class="line"><span>………</span></span>
<span class="line"><span>smtpd_use_tls = yes</span></span>
<span class="line"><span>smtpd_tls_cert_file = /etc/postfix/mail.crt</span></span>
<span class="line"><span>smtpd_tls_key_file = /etc/postfix/mail.key</span></span>
<span class="line"><span>smtpd_tls_security_level = may</span></span>
<span class="line"><span>………</span></span></code></pre></div><p>重启 Postfix 服务以使上述更改生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart postfix</span></span></code></pre></div><p>让我们尝试使用 <code>mailx</code> 客户端将邮件发送到内部本地域和外部域。</p><p>从 <code>pkumar</code> 发送内部本地邮件到 <code>postfixuser</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo &quot;test email&quot; | mailx -s &quot;Test email from Postfix MailServer&quot; -r root@linuxtechi root@linuxtechi</span></span></code></pre></div><p>使用以下命令检查并阅读邮件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /home/postfixuser/Maildir/new/</span></span>
<span class="line"><span># ll</span></span>
<span class="line"><span>total 8</span></span>
<span class="line"><span>-rw-------. 1 postfixuser postfixuser 476 Nov 12 17:34 1573580091.Vfd02I20050b8M635437.server1.crazytechgeek.info</span></span>
<span class="line"><span>-rw-------. 1 postfixuser postfixuser 612 Nov 13 02:40 1573612845.Vfd02I20050bbM466643.server1.crazytechgeek.info</span></span>
<span class="line"><span># cat 1573612845.Vfd02I20050bbM466643.server1.crazytechgeek.info</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Read-Postfixuser-Email-CentOS8.png" alt="Read-Postfixuser-Email-CentOS8"></p><p>从 <code>postfixuser</code> 发送邮件到外部域（<code>root@linuxtechi.com</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo &quot;External Test email&quot; | mailx -s &quot;Postfix MailServer&quot; -r root@linuxtechi root@linuxtechi</span></span></code></pre></div><p>注意：如果你的 IP 没有被任何地方列入黑名单，那么你发送到外部域的邮件将被发送，否则它将被退回，并提示你的 IP 被 spamhaus 之类的数据库列入黑名单。</p><h3 id="检查-postfix-邮件队列" tabindex="-1">检查 Postfix 邮件队列 <a class="header-anchor" href="#检查-postfix-邮件队列" aria-label="Permalink to “检查 Postfix 邮件队列”">​</a></h3><p>使用 <code>mailq</code> 命令列出队列中的邮件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mailq</span></span>
<span class="line"><span>Mail queue is empty</span></span>
<span class="line"><span>#</span></span></code></pre></div><p>完成！我们的 Postfix 配置正常工作了！目前就这样了。我们希望你觉得本教程有见地，并且你可以轻松地设置本地 Postfix 服务器。</p><hr>`,93)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/install-configure-postfix-mailserver-centos-8/"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/install-configure-postfix-mailserver-centos-8/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/james/"},{default:n(()=>[...s[2]||(s[2]=[a("James Kiarie",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:n(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=l(d,[["render",r]]);export{y as __pageData,C as default};
